entries[254314] = { ["name"] = "Waffe - Tyrannei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verzaubert eine Waffe dauerhaft. Ihre PvP-Macht wird um 600 erhöht und ihre Entwaffnungseffekte um 50% verringert. Die Verringerung von Entwaffnungseffekten kann nicht mit ähnlichen Effekten gestapelt werden.\nVerkaufspreis:" }
entries[254315] = { ["name"] = "Formel: Waffe - Tyrannei", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (600)\nBenutzen: Lehrt Euch die dauerhafte Verzauberung einer Waffe. Ihre PvP-Macht wird um 600 erhöht und ihre Entwaffnungseffekte um 50% verringert. Die Verringerung von Entwaffnungseffekten kann nicht mit ähnlichen Effekten gestapelt werden. Erfordert einen Gegenstand der Stufe 600 oder höher.\nVerzaubert eine Waffe dauerhaft. Ihre PvP-Macht wird um 600 erhöht und ihre Entwaffnungseffekte um 50% verringert. Die Verringerung von Entwaffnungseffekten kann nicht mit ähnlichen Effekten gestapelt werden.\nVerkaufspreis:" }
