entries[256054] = { ["name"] = "Uraltes Solei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nErhöht die Zaubermacht um + 190.\nVölker: Mensch , Orc , Zwerg , Nachtelf , Untoter , Tauren , Gnom , Troll , Goblin , Blutelf , Draenei\nBenötigt Stufe 80\nAnlegen: Eure direkten und regelmäßigen Heilzauber haben eine Chance, Euer Tempo [Quellwert] s lang um 975 zu erhöhen. (Procchance: 10%, 45s Abklingzeit)\n\"Stinkend und gummiartig.\"", ["unresolvedValues"] = true }
