entries[260221] = { ["name"] = "Umarmung der Naaru", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Das sanfte Glockenspiel der Naaru ist eine ständige Erinnerung an den Komfort des eigenen Zuhauses.\"" }
entries[260433] = { ["name"] = "Halsband des Sternensplitterwelplings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nMit Rechtsklick Euren Sternensplitterwelpling beschwören oder wieder freigeben.\n\"Lehrt Euch, wie man dieses Haustier beschwört.\"" }
