entries[265330] = { ["name"] = "Satchel of Shining Curiosities", ["text"] = "Wird beim Aufheben gebunden\n\"The satchel trembles with the weight of curious and shining commodities...\"\n<Zum Öffnen rechtsklicken>" }
entries[265414] = { ["name"] = "Platinum Amber", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenötigt Stufe 90\nBenutzen: Schließt Euch selbst in erneuernden Bern ein. Stellt im Verlauf von 10 Sek. 199999 Gesundheit und 300000 Mana wieder her." }
entries[265415] = { ["name"] = "Platinum Vial of Polyformic Acid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 90\nBenutzen: Trinken, um die Polyformsäuretransformation auszulösen." }
entries[265416] = { ["name"] = "Platinum Battle Banner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 90\nBenutzen: Versteckt sich 1 Sek. lang in den Schatten und beschwört einen Kriegsspäher von Salyis. Der Kriegsspäher zieht die Aufmerksamkeit von Monstern in der Nähe auf sich und rennt davon. (10 Min Abklingzeit)" }
entries[265417] = { ["name"] = "Platinum Battle Horn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 90\nBenutzen: Schmettert ins Horn, was Gegner in einem Umkreis von 40 Metern anzieht. (2 Min Abklingzeit)" }
entries[265418] = { ["name"] = "Platinum Rod of Ambershaping", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 90\nBenutzen: Hüllt das Ziel in Bern und verhindert bis zu 1 Min. lang jegliche Handlung. Jeglicher Schaden zerbricht den Bern. Kann nicht gegen Spielercharaktere oder Ziele über Stufe 94 eingesetzt werden. (5 Min Abklingzeit)" }
entries[265419] = { ["name"] = "Platinum potion of Invisibility", ["text"] = "Spielzeug\nBenötigt Stufe 90\nBenutzen: Gewährt dem Anwender 18 Sek. lang Unsichtbarkeit. (10 Min Abklingzeit)" }
entries[265573] = { ["name"] = "Platinum Sacrificial Dagger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ihr hört ein leises Flüstern in Eurem Kopf. Der Dolch sagt Euch, Ihr sollt ihn tief in Euer Herz stoßen. Wagt Ihr es, auf ihn zu hören? (30 Min Abklingzeit)\n\"A ceremonial dagger with the initials T.R.O etched on the hilt. A fourth letter is marred beyond recognition.\"" }
